<script setup lang="ts">
import { Archive, ArrowLeft, ArrowRight, BookOpen, Check, CheckCircle2, ChevronRight, Eye, FileText, Globe2, Info, LoaderCircle, Plus, Save, ShieldCheck, Trash2, X } from 'lucide-vue-next'
import { millionSlots } from '~/shared/millionStages'
import { contentSections, contentUrl, editorTemplates, editorRecord, prepareContent, type CmsKind } from '~/shared/cmsEditor'
const props=defineProps<{record:any}>()
const emit=defineEmits(['close','saved','dirty','deleted'])
const {user}=useAuth()
const pendingUploads=useState('cms-pending-uploads',()=>0)
const deleteDialog=ref<HTMLDialogElement>(),deleteTitle=ref(''),deleting=ref(false),deleteError=ref('')
const savedTitle=computed(()=>String(props.record.title||''))
const form=ref<any>(editorRecord(props.record))
const snapshot=ref(JSON.stringify(form.value)),step=ref(1),saving=ref(false),feedback=ref(''),error=ref(''),fieldErrors=ref<{path:string;label:string;message:string}[]>([])
const action=ref('save'),formElement=ref<HTMLFormElement>()
const section=computed(()=>contentSections.find(x=>x.kind===form.value.kind)!)
const dirty=computed(()=>pendingUploads.value>0||JSON.stringify(form.value)!==snapshot.value)
watch(dirty,value=>emit('dirty',value),{immediate:true})
const kind=computed<CmsKind>(()=>form.value.kind)
const rootTitleLabel=computed(()=>kind.value==='PERSON'||kind.value==='AUTHOR'?'Անուն, ազգանուն':kind.value==='CATEGORY'?'Բաժնի անվանում':kind.value==='MONUMENT'?'Հուշարձանի անվանում':kind.value==='GAME'?(form.value.data.mode==='genius'?'Պնդումը':'Հարցը'):'Վերնագիր')
const rootTitlePlaceholder=computed(()=>({ARTICLE:'Օրինակ՝ Ինչպե՞ս են առաջանում ամպերը',FACT:'Օրինակ՝ Հետաքրքիր փաստ ջրի մասին',PERSON:'Օրինակ՝ Անուն Ազգանուն',CATEGORY:'Օրինակ՝ Աշխարհագրություն',GAME:'Գրիր ամբողջական հարցը…'} as Record<string,string>)[kind.value]||'Գրիր հասկանալի և հակիրճ անվանում')
const hiddenKeys=computed(()=>['id','slug',...(kind.value==='BOOK'?['source','textLicense','coverCredit','coverSource','coverLicense','edition','rightsConfirmed']:[]),...(kind.value==='CATEGORY'?['img','cardVideoPoster']:[]),...(['PERSON','AUTHOR','CATEGORY','MONUMENT'].includes(kind.value)?['name']:[]),...(['GEO_ENTRY','GEO_CATEGORY','BOOK','ARTICLE','FACT','EVENT','WORK','PAGE','VIDEO','SETTING'].includes(kind.value)?['title']:[]),...(kind.value==='GAME'?['mode','question','statement','slot','variant','stage']:[]),...(kind.value==='PERSON'?['portraitTitle','portraitLanguage','workInformation']:[])])
const requiredFields=computed(()=>({GEO_ENTRY:['area','category','detail','source',...(form.value.data.area==='world-facts'?['answer']:form.value.data.area==='records'?['measure','location']:[])],GEO_CATEGORY:['area'],BOOK:['author','topic','description','text'],ARTICLE:['subject','answer','detail'],FACT:['category','text'],PERSON:['years','role','bio'],EVENT:['year','era'],GAME:['explanation'],MONUMENT:['personId','city','location','name','url'],WORK:['personId','description'],PAGE:['text'],VIDEO:['url'],SETTING:['text']} as Record<string,string[]>)[kind.value]||[])
const optionalFields=computed(()=>{
 const definitions:Record<string,{key:string;label:string;value:any}[]>={
 ARTICLE:[{key:'video',label:'Մանրամասն բաժնի վիդեո',value:''},{key:'image',label:'Հոդվածի նկար',value:''},{key:'source',label:'Տեղեկության աղբյուր',value:{name:'',url:''}}],
 CATEGORY:[{key:'image',label:'Բաժնի նկար',value:''},{key:'cardVideo',label:'Քարտի շարժվող նախադիտում',value:''}],
 FACT:[{key:'source',label:'Տեղեկության աղբյուր',value:{name:'',url:''}}],
 PERSON:[{key:'source',label:'Տեղեկության աղբյուր',value:{name:'',url:''}},{key:'biographyDocument',label:'Կենսագրության փաստաթուղթ',value:{name:'',url:''}}],
 MONUMENT:[{key:'openedYear',label:'Բացման տարի',value:undefined},{key:'openedDate',label:'Բացման ամսաթիվ',value:''},{key:'installedYear',label:'Տեղադրման տարի',value:undefined},{key:'sculptor',label:'Քանդակագործ',value:''},{key:'architect',label:'Ճարտարապետ',value:''}],
 }
 return (definitions[kind.value]||[]).filter(x=>!Object.prototype.hasOwnProperty.call(form.value.data,x.key))
})
const preview=computed(()=>prepareContent(form.value))
const previewText=computed(()=>{const d=preview.value.data;return d.detail||d.text||d.bio||d.description||d.explanation||d.details?.intro||''})
const previewImage=computed(()=>{const d=preview.value.data;return d.cover||d.portrait||d.preview||(typeof d.image==='string'?d.image:d.image?.src)||''})
const link=computed(()=>form.value.id?contentUrl(form.value):'')
const statusLabels:Record<string,string>={DRAFT:'Սևագիր',PUBLISHED:'Հրապարակված',ARCHIVED:'Արխիվացված'}
function setGameMode(event:Event){const mode=(event.target as HTMLSelectElement).value;if(form.value.data.mode===mode)return;if((form.value.data.answers?.some((x:string)=>x.trim())||form.value.data.explanation)&&!confirm('Խաղի տեսակը փոխելիս պատասխանների դաշտերը կփոխարինվեն։ Շարունակե՞լ։')){(event.target as HTMLSelectElement).value=form.value.data.mode;return}form.value.data=mode==='genius'?{mode,difficulty:form.value.data.difficulty||'easy',statement:'',correct:true,explanation:'',topic:''}:{...structuredClone(editorTemplates.GAME),mode,difficulty:form.value.data.difficulty||'easy'}}
function setDestination(event:Event){const value=(event.target as HTMLSelectElement).value;form.value.key=value==='custom'?`page-${crypto.randomUUID().slice(0,8)}`:value}
function addOptional(item:{key:string;value:any}){form.value.data[item.key]=item.value===undefined?undefined:structuredClone(item.value)}
function next(){if(!formElement.value?.reportValidity())return;step.value=2;error.value='';feedback.value='';window.scrollTo({top:100,behavior:'smooth'})}
async function save(){
 if(pendingUploads.value)return
 if(!formElement.value?.reportValidity())return
 if(action.value==='archive'&&!confirm('Նյութը կհեռացվի կայքից, բայց կպահպանվի CMS-ում։ Արխիվացնե՞լ։'))return
 saving.value=true;error.value='';feedback.value='';fieldErrors.value=[]
 try{
  const payload=prepareContent(form.value)
  const record=await $fetch<any>('/api/admin/content',{method:form.value.id?'PUT':'POST',query:form.value.id?{id:form.value.id}:{},body:{...payload,action:action.value}})
  form.value=JSON.parse(JSON.stringify(record));snapshot.value=JSON.stringify(form.value)
  feedback.value=action.value==='publish'?'Նյութը հրապարակված է։ Կայքում փոփոխությունը կարող է երևալ մինչև 30 վայրկյանում։':action.value==='archive'?'Նյութը տեղափոխված է արխիվ և այլևս չի երևում կայքում։':'Սևագիրը պահպանված է։ Այն կարող ես շարունակել խմբագրել ավելի ուշ։'
  emit('saved',record)
 }catch(e:any){error.value=e.data?.statusMessage||'Չհաջողվեց պահպանել։ Ստուգիր կապը և փորձիր կրկին։';fieldErrors.value=e.data?.data?.fields||[];if(fieldErrors.value.length)step.value=1}finally{saving.value=false}
}
function openDelete(){deleteTitle.value='';deleteError.value='';deleteDialog.value?.showModal()}
async function permanentlyDelete(){
 if(deleting.value||deleteTitle.value!==savedTitle.value)return
 deleting.value=true;deleteError.value=''
 try{
  await $fetch('/api/admin/content',{method:'DELETE',query:{id:form.value.id,permanent:'true'},body:{title:deleteTitle.value,version:props.record.version}})
  emit('dirty',false);deleteDialog.value?.close();emit('deleted')
 }catch(e:any){deleteError.value=e.data?.statusMessage||'Չհաջողվեց ջնջել։ Փորձիր կրկին։'}finally{deleting.value=false}
}
function submit(actionName:string){action.value=actionName;formElement.value?.requestSubmit()}
</script>
<template>
  <section class="content-editor">
    <header class="editor-heading"><button type="button" class="back-button" :disabled="saving||pendingUploads>0" @click="emit('close')"><ArrowLeft :size="16"/>Վերադառնալ ցանկին</button><div class="editor-state"><span v-if="dirty" class="unsaved"><span/>Չպահպանված փոփոխություններ</span><span v-else-if="form.id" class="saved"><Check :size="14"/>Պահպանված է</span></div></header>
    <div class="editor-title-row"><div><p class="editor-eyebrow">{{section.label}}</p><h1>{{form.id?'Խմբագրել նյութը':`Ավելացնել ${section.singular}`}}</h1></div><span class="status-badge" :class="form.status?.toLowerCase()">{{statusLabels[form.status]||'Նոր նյութ'}}</span></div>
    <div class="editor-steps"><button type="button" :class="{active:step===1}" @click="step=1"><span>1</span><div><strong>Լրացրու նյութը</strong><small>Տեքստ, բաժին և նկարներ</small></div></button><ChevronRight :size="17"/><button type="button" :class="{active:step===2}" @click="next"><span>2</span><div><strong>Ստուգիր և հրապարակիր</strong><small>Նախադիտում և վերջնական ստուգում</small></div></button></div>
    <p v-if="feedback" class="editor-feedback" role="status"><CheckCircle2 :size="20"/><span>{{feedback}} <a v-if="form.publishedData&&link" :href="link" target="_blank" rel="noopener">Դիտել կայքում ↗</a></span></p>
    <div v-if="error" class="editor-error" role="alert"><strong>{{error}}</strong><ul v-if="fieldErrors.length"><li v-for="item in fieldErrors" :key="item.path">{{item.label}} · {{item.message}}</li></ul><button v-if="fieldErrors.length" type="button" @click="step=1">Վերադառնալ դաշտերին</button></div>
    <form ref="formElement" class="editor-layout" @submit.prevent="save">
      <div class="editor-main">
        <div v-show="step===1" class="editor-fields">
          <section class="editor-panel"><div class="panel-heading"><span class="panel-number">01</span><div><h2>Հիմնական տեղեկություններ</h2><p>Աստղանիշով դաշտերն անհրաժեշտ են նյութը լրացնելու համար։</p></div></div>
            <div v-if="kind==='GAME'" class="editor-field"><label for="editor-game">Ո՞ր խաղի համար է հարցը</label><select id="editor-game" :value="form.data.mode" @change="setGameMode"><option value="million">Միլիոնատեր</option><option value="genius">Ճիշտ / սխալ</option><option value="logic">Տրամաբանություն</option></select></div>
            <div v-if="kind==='GAME'&&form.data.mode==='million'" class="editor-field"><label for="million-slot">Ո՞ր հարցի բանկում ավելացնել <span>*</span></label><select id="million-slot" v-model="form.data.slot" required><option v-for="slot in millionSlots" :key="slot.value" :value="slot.value">{{slot.label}}</option></select><p>Այս հարցը կընտրվի միայն նշված հարցահամարի համար։ Նույն բանկում կարող ես ավելացնել բազմաթիվ հարցեր։ «Փոխել հարցը» օգնությունն էլ կընտրի նույն բանկից։</p></div><div class="editor-field"><label for="editor-title">{{rootTitleLabel}} <span>*</span></label><textarea v-if="kind==='GAME'" id="editor-title" v-model="form.title" rows="3" required maxlength="500" :placeholder="rootTitlePlaceholder"/><input v-else id="editor-title" v-model="form.title" required maxlength="500" :placeholder="rootTitlePlaceholder"></div>
            <div v-if="kind==='PAGE'" class="editor-field"><label for="page-destination">Որտե՞ղ ցուցադրել</label><select id="page-destination" :value="['about','support'].includes(form.key)?form.key:'custom'" :disabled="!!form.id" @change="setDestination"><option value="about">«Մեր մասին» էջում</option><option value="support">«Աջակցիր COGNITIO-ին» էջում</option><option value="custom">Առանձին նոր էջ</option></select></div>
            <div v-if="kind==='SETTING'&&!form.id" class="editor-field"><label for="setting-destination">Որտե՞ղ օգտագործել տեքստը</label><select id="setting-destination" v-model="form.key"><option value="footer">Կայքի ներքևի ստորագրություն</option></select><p>Այս տեքստը կերևա կայքի բոլոր էջերի ներքևում։</p></div>
          </section>
          <section class="editor-panel"><div class="panel-heading"><span class="panel-number">02</span><div><h2>Նյութի բովանդակությունը</h2><p>Լրացրու տեքստը, ընտրիր համապատասխան թեման և ավելացրու նկար։</p></div></div><AdminFields v-model="form.data" :kind="kind" :hidden-keys="hiddenKeys" :required-fields="requiredFields" :disabled-fields="form.id?['year','index','personId',...(kind==='GEO_CATEGORY'?['area']:[])]:[]"/><div v-if="optionalFields.length" class="optional-fields"><p>Կարող ես նաև ավելացնել</p><button v-for="item in optionalFields" :key="item.key" type="button" @click="addOptional(item)"><Plus :size="14"/>{{item.label}}</button></div></section>
          <section v-if="kind==='ARTICLE'" class="editor-panel"><div class="panel-heading"><span class="panel-number">03</span><div><h2>Հեղինակ</h2><p>Լրացրու, եթե ցանկանում ես նշել նյութի հեղինակին։</p></div></div><AdminReferenceField v-model="form.authorId" kind="AUTHOR" value-key="id" placeholder="Առանց նշված հեղինակի"/></section>
          <details class="technical-details"><summary>Լրացուցիչ կարգավորումներ</summary><div><label>Նյութի հասցեի նշում<input v-model="form.key" :disabled="!!form.id||kind==='EVENT'||kind==='WORK'" maxlength="200" required></label><p>Ստեղծվում է ինքնաշխատ։ Փոփոխելը պարտադիր չէ։ Գործող նյութի հասցեն չի փոխվում, որպեսզի հին հղումները պահպանվեն։</p><label>Ներքին ամփոփում<textarea v-model="form.summary" rows="2" maxlength="5000"/></label><p>Սա խմբագրի նշումն է․ հանրային տեքստը լրացրու հիմնական բովանդակության դաշտերում։</p></div></details>
        </div>
        <section v-show="step===2" class="editor-panel preview-panel"><div class="panel-heading"><span class="panel-number"><Eye :size="19"/></span><div><h2>Նախադիտում</h2><p>Ստուգիր բովանդակությունը։ Այստեղ ներկայացված է ընդհանուր նախադիտում․ կայքի իրական էջի դասավորությունը կարող է տարբերվել։</p></div></div><article class="article-preview"><p class="preview-label">COGNITIO · {{section.label}}</p><img v-if="previewImage" :src="previewImage" :alt="form.title" loading="lazy"><h2>{{form.title||'Նյութի վերնագիրը'}}</h2><p v-if="kind==='GEO_ENTRY'&&preview.data.measure" class="preview-lead">{{preview.data.measure}} · {{preview.data.location}}</p><p v-if="preview.data.answer" class="preview-lead">{{preview.data.answer}}</p><p class="preview-text">{{previewText||'Այստեղ կհայտնվի քո լրացրած տեքստը։'}}</p><section v-for="(block,i) in preview.data.sections||preview.data.biographySections||preview.data.details?.sections||[]" :key="i"><h3>{{block.title||block.heading}}</h3><p>{{block.text||block.body}}</p><img v-if="block.image" :src="block.image" :alt="block.title||form.title" loading="lazy"></section><p v-if="preview.data.example" class="preview-example"><strong>Օրինակ</strong>{{preview.data.example}}</p><ul v-if="preview.data.answers"><li v-for="(answer,i) in preview.data.answers" :key="i" :class="{correct:preview.data.correct===i}"><Check v-if="preview.data.correct===i" :size="16"/>{{answer||`Տարբերակ ${i+1}`}}</li></ul><p v-if="typeof preview.data.correct==='boolean'">Ճիշտ պատասխանը՝ {{preview.data.correct?'Ճիշտ է':'Սխալ է'}}</p><a v-if="preview.data.source?.url" :href="preview.data.source.url" target="_blank" rel="noopener noreferrer">Աղբյուր՝ {{preview.data.source.name||preview.data.source.url}} ↗</a></article><button type="button" class="editor-secondary" @click="step=1"><ArrowLeft :size="15"/>Վերադառնալ խմբագրմանը</button></section>
      </div>
      <aside class="editor-sidebar">
        <section class="editor-panel publish-panel"><div class="publish-icon"><Globe2 :size="23"/></div><h2>Պատրա՞ստ է քո նյութը</h2><p>Պահպանիր որպես սևագիր կամ նախադիտումից հետո հրապարակիր կայքում։</p><div class="publish-checklist"><span><Check :size="14"/>Ստուգիր անվանումն ու տեքստը</span><span><Check :size="14"/>Համոզվիր, որ աղբյուրը ճիշտ է</span><span><Check :size="14"/>Ստուգիր նկարի օգտագործման իրավունքը</span></div><button v-if="step===1" type="button" class="editor-primary" :disabled="saving||pendingUploads>0" @click="next"><Eye :size="17"/>Նախադիտել նյութը<ArrowRight :size="16"/></button><button v-else type="button" class="editor-primary" :disabled="saving||pendingUploads>0" @click="submit('publish')"><LoaderCircle v-if="saving" class="spinning" :size="17"/><Globe2 v-else :size="17"/>{{saving?'Պահպանվում է…':'Հրապարակել կայքում'}}</button><button type="button" class="editor-secondary" :disabled="saving||pendingUploads>0" @click="submit('save')"><Save :size="16"/>Պահպանել սևագիր</button><a v-if="form.publishedData&&link" class="view-live" :href="link" target="_blank" rel="noopener">Դիտել հրապարակված էջը ↗</a><button v-if="form.id&&form.status!=='ARCHIVED'" type="button" class="archive-button" :disabled="saving||pendingUploads>0" @click="submit('archive')"><Archive :size="14"/>Տեղափոխել արխիվ</button><button v-if="form.id&&user?.role==='ADMIN'" type="button" class="permanent-delete-button" :disabled="saving||pendingUploads>0" @click="openDelete"><Trash2 :size="14"/>Ջնջել անվերադարձ</button><p class="publish-footnote"><ShieldCheck :size="14"/>Սևագիրը չի ցուցադրվում այցելուներին։ Հրապարակված նյութի փոփոխությունները տեսանելի կդառնան նորից հրապարակելուց հետո։</p></section>
        <section v-if="kind==='PERSON'||kind==='MONUMENT'" class="editor-note"><Info :size="18"/><div><h3>Ստուգված տեղեկություններ</h3><p>Կենսագրություն կամ դիմանկար ավելացնելիս ստուգիր նաև այդ մարդուն նվիրված հուշարձանները։ Յուրաքանչյուր հուշարձանի համար նշիր աղբյուրը, իրական վայրի լուսանկարը և նկարի արտոնագիրը։ Անորոշ տարեթիվ կամ հեղինակ մի լրացրու։</p></div></section>
        <section v-if="kind==='WORK'" class="editor-note"><Info :size="18"/><div><h3>Պահպանիր հերթականությունը</h3><p>Սկզբում մարդու էջում ավելացրու ստեղծագործության անվանումը։ Այստեղ լրացրու նույն անվանումը և դրա համարը։ Գործող ստեղծագործությունների տեղերը մի փոխիր։</p></div></section>
        <section v-if="kind==='GAME'" class="editor-note"><Info :size="18"/><div><h3>Հարցերի քանակը</h3><p>Միլիոնատերի յուրաքանչյուր բարդության համար պետք է առնվազն 30 հրապարակված հարց, մյուս երկու խաղերի համար՝ առնվազն 10։</p></div></section>
      </aside>
    </form>
    <dialog ref="deleteDialog" class="delete-dialog" aria-labelledby="permanent-delete-title" @cancel="deleting&&$event.preventDefault()">
      <form @submit.prevent="permanentlyDelete">
        <span class="delete-symbol"><Trash2 :size="24"/></span>
        <h2 id="permanent-delete-title">Ջնջե՞լ նյութն անվերադարձ</h2>
        <p>Նյութը, դրա սևագիրն ու հրապարակված տարբերակը ամբողջությամբ կհեռացվեն բազայից։ CMS-ից վերականգնել հնարավոր չի լինի։ Նկարի ֆայլերն ու առանձին կապված նյութերը չեն ջնջվի։</p>
        <label for="permanent-delete-confirm">Հաստատելու համար գրիր նյութի ամբողջական անվանումը․<strong>{{savedTitle}}</strong></label>
        <input id="permanent-delete-confirm" v-model="deleteTitle" autofocus required autocomplete="off" :disabled="deleting" :placeholder="savedTitle">
        <p v-if="deleteError" class="delete-error" role="alert">{{deleteError}}</p>
        <div class="delete-dialog-actions"><button type="button" class="editor-secondary" :disabled="deleting" @click="deleteDialog?.close()">Չեղարկել</button><button type="submit" class="delete-confirm" :disabled="deleting||deleteTitle!==savedTitle"><LoaderCircle v-if="deleting" :size="15" class="spinning"/><Trash2 v-else :size="15"/>{{deleting?'Ջնջվում է…':'Ջնջել անվերադարձ'}}</button></div>
      </form>
    </dialog>
  </section>
